static void dump(const ROMol &m, const std::string &label) {
  std::cout << "--- " << label << "\n";
  for (const auto b : m.bonds()) {
    std::cout << "  bond " << b->getIdx() << " " << b->getBeginAtomIdx() << "-"
              << b->getEndAtomIdx() << " type=" << b->getBondType()
              << " stereo=" << b->getStereo() << " nSA="
              << b->getStereoAtoms().size() << " dir=" << b->getBondDir()
              << "\n";
  }
}

int main(int argc, char **argv) {
  std::ifstream in(argv[1]);
  std::ostringstream buf; buf << in.rdbuf();
  std::unique_ptr<RWMol> mol(MolBlockToMol(buf.str()));
  std::cout << "input smiles: " << MolToSmiles(*mol) << "\n";
  dump(*mol, "input");
  MolStandardize::TautomerEnumerator te;
  te.setRemoveBondStereo(false);
  auto copy = te;
  copy.setReassignStereo(false);
  auto res = copy.enumerate(*mol);
  std::cout << "n tautomers: " << res.size() << "\n";
  for (size_t i = 0; i < res.size(); ++i) {
    dump(*res.at(i), "taut " + std::to_string(i));
    try {
      std::cout << "  smiles=" << MolToSmiles(*res.at(i)) << "\n";
    } catch (const std::exception &e) {
      std::cout << "  SMILES FAILED: " << e.what() << "\n";
    }
  }
  return 0;
}
